  boards: 5,
  roOnLoad: 5,
  widthBefore: '500px',
  widthAfter: '400px',
  roAfterNewBoard: 6,
  roAfterRedraws: 8,
  liveAfterRedraws: 6,
  liveAfterDestroy: 5,
};
